export const score = (value) => Number(value).toFixed(2);
export const score1 = (value) => Number(value).toFixed(1);

/** One task's five trajectories, read at build time for static previews. */
export function loadRun(key) {
  const file = path.join(process.cwd(), "public/diabagent/runs", `${key}.json.gz`);
  return JSON.parse(gunzipSync(fs.readFileSync(file)).toString());
}

/** Catalogue entry for a task key. */
export function findTask(key) {
  for (const template of templates) {
    const instance = template.instances.find((row) => row.key === key);
    if (instance) return { template, instance };
  }
  throw new Error(`Unknown DiabAgent task: ${key}`);
}
